import itertools
from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType

n = 11
fixed_edges = [(3,7), (2,9), (0,9)]

all_possible_edges = [(i,j) for i in range(n) for j in range(i+1,n)]

# Create variables for each possible edge
edge_vars = {}
var_to_edge = {}
var_count = 1
for e in all_possible_edges:
    edge_vars[e] = var_count
    var_to_edge[var_count] = e
    var_count += 1

# Create variables for coloring (4 colors)
color_vars = {}
for i in range(n):
    for c in range(4):
        color_vars[(i,c)] = var_count
        var_count += 1

total_vars = var_count - 1

solver = Glucose3()

# Fixed edges must be present
for e in fixed_edges:
    solver.add_clause([edge_vars[e]])

# Edge count constraints: between 17 and 19
edge_var_list = [edge_vars[e] for e in all_possible_edges]

# At least 17 edges
atleast17 = CardEnc.atleast(lits=edge_var_list, bound=17, top_id=total_vars, encoding=EncType.seqcounter)
for clause in atleast17.clauses:
    solver.add_clause(clause)

# At most 19 edges
atmost19 = CardEnc.atmost(lits=edge_var_list, bound=19, top_id=total_vars, encoding=EncType.seqcounter)
for clause in atmost19.clauses:
    solver.add_clause(clause)

# Degree constraints
for i in range(n):
    incident_edges = []
    for j in range(n):
        if i < j:
            incident_edges.append(edge_vars[(i,j)])
        elif i > j:
            incident_edges.append(edge_vars[(j,i)])
    # degree >= 3
    atleast3 = CardEnc.atleast(lits=incident_edges, bound=3, top_id=total_vars, encoding=EncType.seqcounter)
    for clause in atleast3.clauses:
        solver.add_clause(clause)
    # degree <= 5
    atmost5 = CardEnc.atmost(lits=incident_edges, bound=5, top_id=total_vars, encoding=EncType.seqcounter)
    for clause in atmost5.clauses:
        solver.add_clause(clause)

# Coloring constraints
# Each vertex gets exactly one color
for i in range(n):
    atleast1 = CardEnc.atleast(lits=[color_vars[(i,c)] for c in range(4)], bound=1, top_id=total_vars, encoding=EncType.seqcounter)
    for clause in atleast1.clauses:
        solver.add_clause(clause)
    atmost1 = CardEnc.atmost(lits=[color_vars[(i,c)] for c in range(4)], bound=1, top_id=total_vars, encoding=EncType.seqcounter)
    for clause in atmost1.clauses:
        solver.add_clause(clause)

# Adjacent vertices cannot have same color
for (u,v) in all_possible_edges:
    for c in range(4):
        # If edge (u,v) is present, then not (color[u]=c and color[v]=c)
        solver.add_clause([-edge_vars[(u,v)], -color_vars[(u,c)], -color_vars[(v,c)]])

print("Solving...")
result = solver.solve()
print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    selected_edges = []
    for var, val in enumerate(model, start=1):
        if val > 0 and var in var_to_edge:
            selected_edges.append(var_to_edge[var])

    print(f"Selected edges ({len(selected_edges)}): {sorted(selected_edges)}")

    # Check degrees
    deg = [0]*n
