import itertools
from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType

n = 11
fixed_edges = [(3,7), (2,9), (0,9)]

all_possible_edges = [(i,j) for i in range(n) for j in range(i+1,n)]

# Create variables for each possible edge
edge_vars = {}
var_to_edge = {}
var_count = 1
for e in all_possible_edges:
    edge_vars[e] = var_count
    var_to_edge[var_count] = e
    var_count += 1

total_vars = var_count - 1

# Let's try each edge count from 17 to 19
for target_edges in range(17, 20):
    print(f"\n=== Trying with exactly {target_edges} edges ===")
    solver = Glucose3()

    for e in fixed_edges:
        solver.add_clause([edge_vars[e]])

    edge_var_list = [edge_vars[e] for e in all_possible_edges]

    # Exactly target_edges edges
    exactly = CardEnc.equals(lits=edge_var_list, bound=target_edges, top_id=total_vars, encoding=EncType.seqcounter)
    for clause in exactly.clauses:
        solver.add_clause(clause)

    # Degree constraints
    for i in range(n):
        incident_edges = []
        for j in range(n):
            if i < j:
                incident_edges.append(edge_vars[(i,j)])
            elif i > j:
                incident_edges.append(edge_vars[(j,i)])
        atleast3 = CardEnc.atleast(lits=incident_edges, bound=3, top_id=total_vars, encoding=EncType.seqcounter)
        for clause in atleast3.clauses:
            solver.add_clause(clause)
        atmost5 = CardEnc.atmost(lits=incident_edges, bound=5, top_id=total_vars, encoding=EncType.seqcounter)
        for clause in atmost5.clauses:
            solver.add_clause(clause)

    result = solver.solve()
    print(f"  Satisfiable: {result}")

    if result:
        model = solver.get_model()
        selected_edges = []
        for var, val in enumerate(model, start=1):
            if val > 0 and var in var_to_edge:
                selected_edges.append(var_to_edge[var])

        print(f"  Edges ({len(selected_edges)}): {sorted(selected_edges)}")
        deg = [0]*n
        for u,v in selected_edges:
            deg[u] += 1
            deg[v] += 1
        print(f"  Degrees: {deg}")
        print(f"  Min degree: {min(deg)}, Max degree: {max(deg)}")

        # Now check chromatic number
        # First check if 2-colorable (bipartite)
        # Build adjacency
        adj = {i: set() for i in range(n)}
        for u,v in selected_edges:
            adj[u].add(v)
            adj[v].add(u)

        # Check bipartite via BFS
        color = {}
        is_bipartite = True
        for start in range(n):
            if start not in color:
                color[start] = 0
                queue = [start]
                while queue:
                    v = queue.pop(0)
                    for u in adj[v]:
                        if u not in color:
                            color[u] = 1 - color[v]
                            queue.append(u)
                        elif color[u] == color[v]:
                            is_bipartite = False
                            break
                if not is_bipartite:
                    break

        print(f"  Is bipartite (2-colorable): {is_bipartite}")

        if is_bipartite:
            print(f"  -> Chromatic number = 2, INVALID (need >= 3)")
            continue

        # Check if 3-colorable using SAT
        solver3 = Glucose3()
        # Create color variables for 3 colors
        color_vars3 = {}
        cv_count = 1
        for i in range(n):
            for c in range(3):
                color_vars3[(i,c)] = cv_count
                cv_count += 1

        # Each vertex gets exactly one color
        for i in range(n):
            atleast1 = CardEnc.atleast(lits=[color_vars3[(i,c)] for c in range(3)], bound=1, top_id=cv_count-1, encoding=EncType.seqcounter)
            for clause in atleast1.clauses:
                solver3.add_clause(clause)
            atmost1 = CardEnc.atmost(lits=[color_vars3[(i,c)] for c in range(3)], bound=1, top_id=cv_count-1, encoding=EncType.seqcounter)
            for clause in atmost1.clauses:
                solver3.add_clause(clause)

        # Adjacent vertices different colors
        for (u,v) in selected_edges:
            for c in range(3):
                solver3.add_clause([-color_vars3[(u,c)], -color_vars3[(v,c)]])

        result3 = solver3.solve()
        print(f"  3-colorable: {result3}")

        if result3:
            print(f"  -> Chromatic number = 3, VALID!")
            # Get the 3-coloring
            model3 = solver3.get_model()
            coloring3 = {}
            for i in range(n):
                for c in range(3):
                    if model3[color_vars3[(i,c)]-1] > 0:
                        coloring3[i] = c
                        break
            print(f"  3-coloring: {coloring3}")
            print(f"\n  SOLUTION FOUND!")
            print(f"  Edges: {sorted(selected_edges)}")
            break
        else:
            # Check if 4-colorable
            solver4 = Glucose3()
            color_vars4 = {}
            cv_count = 1
            for i in range(n):
                for c in range(4):
                    color_vars4[(i,c)] = cv_count
                    cv_count += 1

            for i in range(n):
                atleast1 = CardEnc.atleast(lits=[color_vars4[(i,c)] for c in range(4)], bound=1, top_id=cv_count-1, encoding=EncType.seqcounter)
                for clause in atleast1.clauses:
                    solver4.add_clause(clause)
                atmost1 = CardEnc.atmost(lits=[color_vars4[(i,c)] for c in range(4)], bound=1, top_id=cv_count-1, encoding=EncType.seqcounter)
                for clause in atmost1.clauses:
                    solver4.add_clause(clause)

            for (u,v) in selected_edges:
                for c in range(4):
                    solver4.add_clause([-color_vars4[(u,c)], -color_vars4[(v,c)]])

            result4 = solver4.solve()
            print(f"  4-colorable: {result4}")

            if result4:
                print(f"  -> Chromatic number = 4, VALID!")
                model4 = solver4.get_model()
                coloring4 = {}
                for i in range(n):
                    for c in range(4):
                        if model4[color_vars4[(i,c)]-1] > 0:
                            coloring4[i] = c
                            break
                print(f"  4-coloring: {coloring4}")
                print(f"\n  SOLUTION FOUND!")
                print(f"  Edges: {sorted(selected_edges)}")
                break
            else:
                print(f"  -> Not 4-colorable, INVALID")
    else:
        print(f"  No graph found with {target_edges} edges satisfying degree constraints")
